import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(!Arrays.equals(s.maxSlidingWindow(new int[]{1,3,-1,-3,5,3,6,7},3),new int[]{3,3,5,5,6,7})||!Arrays.equals(s.maxSlidingWindow(new int[]{1},1),new int[]{1}))throw new AssertionError();Random r=new Random(91);for(int t=0;t<2000;t++){int n=1+r.nextInt(60),k=1+r.nextInt(n);int[] a=new int[n],w=new int[n-k+1];for(int i=0;i<n;i++)a[i]=r.nextInt(21)-10;for(int i=0;i<w.length;i++){w[i]=Integer.MIN_VALUE;for(int j=i;j<i+k;j++)w[i]=Math.max(w[i],a[j]);}if(!Arrays.equals(s.maxSlidingWindow(a,k),w))throw new AssertionError();}int[] a=new int[100000];Arrays.fill(a,-10000);if(s.maxSlidingWindow(a,100000)[0]!=-10000)throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}}